	recipes.TfuiExampleAbout = react.RegisterWrapperRecipe("TfuiExampleAbout", builtin.Window, function(_params)
		return builtin.Window {
			id = "tfui_example_en.new_window",
			title = "About",
			initialX = 0.1,
			initialY = 0.1,
			closable = true,
			movable = true,
			expanded = false,
			onClose = function()
				pcall(function()
					api.gui.byId.setVisible("tfui_example_en.new_window", false)
				end)
			end,
			meta = {
				class = "tfui-example-en-new-window-window, dialog",
			},
			content = builtin.BoxLayout {
				orientation = builtin.type.Orientation.Vertical,
				meta = {
					class = "tfui-7b3ea977",
				},
				children = {
					builtin.RichTextView {
						text = "This window is an example made with TFUI, the interface editor for Transport Fever 3.\n\nAll values shown are sample data: no logic is attached.",
						meta = {
							class = "tfui-8131854b",
						},
					},
					builtin.BoxLayout {
						orientation = builtin.type.Orientation.Horizontal,
						children = {
							builtin.Component {
								meta = {
									class = "horizontal-spacer",
								},
							},
							builtin.Button {
								onClick = function()
					pcall(function()
						api.gui.byId.setVisible("tfui_example_en.new_window", false)
					end)
				end,
								meta = {
									class = "primary, tfui-06dd215f",
								},
								content = builtin.TextView {
