	end)
	
	recipes.TfuiExampleEnModButton = react.RegisterPluginRecipe(main_mod_button_area.MainModButtonAreaExtension, "TfuiExampleEnModButton", function(_params)
		return builtin.BoxLayout {
			orientation = builtin.type.Orientation.Horizontal,
			children = {
				builtin.Button {
					onClick = function()
					local wapi = game_react_globals.getDefaultWindowApi()
					if wapi == nil then
						return
					end
					wapi.addSingletonWindow(recipes.TfuiExampleEnMainWindow, {})
					pcall(function()
						api.gui.byId.setVisible("tfui_example_en.main", true)
					end)
					wapi.moveSingletonWindowToFront(recipes.TfuiExampleEnMainWindow)
				end,
					meta = {
						class = "secondary",
						tooltip = "TFUI — Example",
					},
					content = builtin.TextView {
						text = "TFUI — Example",
						meta = {
							class = "font-scale-body",
						},
					},
				},
			},
		}
	end)
	
	return {
		TfuiExampleEnMainWindow = recipes.TfuiExampleEnMainWindow,
		TfuiExampleAbout = recipes.TfuiExampleAbout,
		TfuiExampleEnModButton = recipes.TfuiExampleEnModButton,
	}
